/**
 * Rework public.devices for the device registry and add public.device_activity_log
 *
 * A device is one app installation (app_id + installation_id, generated by the app). riwayat-device-management
 * registers it at login and on every session refresh, keeps its FCM push token, and signs it out or revokes it.
 *
 * public.devices (created by 1779850000047 with every column nullable and no unique key besides the primary key) gets:
 *   - app_id (CUSTOMER_APP / PARTNER_APP / RIDER_APP) and installation_id;
 *   - revoke_reason: the reason code an admin picked when revoking the device;
 *   - NOT NULL on app_id, installation_id, owner_type, owner_id, platform, status (status defaults to ACTIVE);
 *   - CHECK on status (ACTIVE / SIGNED_OUT / REVOKED) and platform (ANDROID / IOS / WEB);
 *   - one row per installation: unique (app_id, installation_id) among rows not deleted;
 *   - one device per push token: unique fcm_token;
 *   - an index on the owner for "devices of this user" and the push lookup;
 *   - is_deleted is kept for now: the released riwayat-device-management still filters on it. The new module uses
 *     deleted_at like everywhere else; drop is_deleted in a later migration once no deployed code reads it.
 * App version, OS version, model and locale go in the existing device_details jsonb.
 *
 * up() is idempotent. The NOT NULL step stops with an error if rows with empty values exist (nothing has
 * written to the table so far, so it should be empty; such rows need a manual decision).
 *
 * down() reverses the schema changes; it drops device_activity_log and the three new columns, so the
 * registrations and their history are lost.
 */

exports.up = (pgm) => {
  pgm.sql(`
DO $devices$
BEGIN
  IF to_regclass('public.devices') IS NULL THEN
    RAISE EXCEPTION 'public.devices does not exist; apply 1779850000047 first';
  END IF;

  ALTER TABLE public.devices ADD COLUMN IF NOT EXISTS app_id varchar(30);
  ALTER TABLE public.devices ADD COLUMN IF NOT EXISTS installation_id varchar(100);
  ALTER TABLE public.devices ADD COLUMN IF NOT EXISTS revoke_reason varchar(50);

  IF EXISTS (
    SELECT 1 FROM public.devices
     WHERE app_id IS NULL OR installation_id IS NULL OR owner_type IS NULL OR owner_id IS NULL
        OR platform IS NULL OR status IS NULL
  ) THEN
    RAISE EXCEPTION 'public.devices has rows without app_id, installation_id, owner, platform or status; fix them before this migration';
  END IF;

  ALTER TABLE public.devices
    ALTER COLUMN status SET DEFAULT 'ACTIVE',
    ALTER COLUMN app_id SET NOT NULL,
    ALTER COLUMN installation_id SET NOT NULL,
    ALTER COLUMN owner_type SET NOT NULL,
    ALTER COLUMN owner_id SET NOT NULL,
    ALTER COLUMN platform SET NOT NULL,
    ALTER COLUMN status SET NOT NULL;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.devices'::regclass AND conname = 'chk_devices_status') THEN
    ALTER TABLE public.devices ADD CONSTRAINT chk_devices_status CHECK (status IN ('ACTIVE', 'SIGNED_OUT', 'REVOKED'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.devices'::regclass AND conname = 'chk_devices_platform') THEN
    ALTER TABLE public.devices ADD CONSTRAINT chk_devices_platform CHECK (platform IN ('ANDROID', 'IOS', 'WEB'));
  END IF;

END
$devices$;
`);

  pgm.createIndex('devices', ['app_id', 'installation_id'], {
    name: 'uq_devices_installation', unique: true, where: 'deleted_at IS NULL', ifNotExists: true,
  });
  pgm.createIndex('devices', 'fcm_token', {
    name: 'uq_devices_fcm_token', unique: true, where: 'fcm_token IS NOT NULL', ifNotExists: true,
  });
  pgm.createIndex('devices', ['owner_type', 'owner_id'], { name: 'idx_devices_owner', ifNotExists: true });

  pgm.createTable(
    'device_activity_log',
    {
      id:                   { type: 'uuid',        primaryKey: true, default: pgm.func('gen_random_uuid()'), notNull: true },
      device_id:            { type: 'uuid',        notNull: true, references: 'devices', onDelete: 'CASCADE' },
      owner_type:           { type: 'varchar(50)', notNull: true },
      owner_id:             { type: 'uuid',        notNull: true },
      event_type:           { type: 'varchar(50)', notNull: true },
      performed_by_details: { type: 'jsonb' },
      event_details:        { type: 'jsonb' },
      occurred_at:          { type: 'timestamptz', notNull: true, default: pgm.func('now()') },
    },
    { ifNotExists: true },
  );
  // ifNotExists must not silently keep a table of another shape (e.g. from an old hand-run script).
  pgm.sql(`
DO $log$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns
       WHERE table_schema = 'public' AND table_name = 'device_activity_log'
         AND (column_name, data_type) IN (
           ('id', 'uuid'), ('device_id', 'uuid'), ('owner_type', 'character varying'), ('owner_id', 'uuid'),
           ('event_type', 'character varying'), ('performed_by_details', 'jsonb'), ('event_details', 'jsonb'),
           ('occurred_at', 'timestamp with time zone'))) <> 8 THEN
    RAISE EXCEPTION 'public.device_activity_log exists with an unexpected shape; drop or migrate it first';
  END IF;
END
$log$;
`);
  pgm.createIndex('device_activity_log', ['device_id', { name: 'occurred_at', sort: 'DESC' }], {
    name: 'idx_device_activity_log_device', ifNotExists: true,
  });
};

exports.down = (pgm) => {
  pgm.dropTable('device_activity_log', { ifExists: true });
  pgm.dropIndex('devices', [], { name: 'idx_devices_owner', ifExists: true });
  pgm.dropIndex('devices', [], { name: 'uq_devices_fcm_token', ifExists: true });
  pgm.dropIndex('devices', [], { name: 'uq_devices_installation', ifExists: true });
  pgm.sql(`
ALTER TABLE public.devices DROP CONSTRAINT IF EXISTS chk_devices_platform;
ALTER TABLE public.devices DROP CONSTRAINT IF EXISTS chk_devices_status;
ALTER TABLE public.devices
  ALTER COLUMN owner_type DROP NOT NULL,
  ALTER COLUMN owner_id DROP NOT NULL,
  ALTER COLUMN platform DROP NOT NULL,
  ALTER COLUMN status DROP NOT NULL,
  ALTER COLUMN status DROP DEFAULT;
ALTER TABLE public.devices DROP COLUMN IF EXISTS revoke_reason;
ALTER TABLE public.devices DROP COLUMN IF EXISTS installation_id;
ALTER TABLE public.devices DROP COLUMN IF EXISTS app_id;
`);
};
